    export const getUnlinkInsightUrl = (projectId: string,
    recommendationId: string,
    insightId: string,
    params: UnlinkInsightParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {

    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : String(value))
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/api/projects/${projectId}/recommendations/${recommendationId}/insights/${insightId}?${stringifiedParams}` : `/api/projects/${projectId}/recommendations/${recommendationId}/insights/${insightId}`
}

